-- Reference seed (part 03.02): the feature flag (OFF by default, ON in development and test), the document type of the reference
-- form (numbered when submitted) and the reference form's definition (src/shared/forms/sample-request.js; a test keeps them equal).
INSERT OR IGNORE INTO core_feature_flags (key, description, default_enabled, environment, enabled, created_by, source_type)
VALUES ('ff.ui.p0302', 'Part 03.02 form components and data-entry framework', 0, NULL, 0, 'migration', 'reference_seed');
INSERT OR IGNORE INTO core_feature_flags (key, description, default_enabled, environment, enabled, created_by, source_type)
SELECT 'ff.ui.p0302', 'Part 03.02 form components and data-entry framework', 0, env.name, 1, 'migration', 'reference_seed'
FROM (SELECT 'development' AS name UNION ALL SELECT 'test') AS env;
INSERT OR IGNORE INTO core_document_types (code, name, module, retention_class, statutory, assign_at, created_by, source_type)
VALUES ('SAMPLE_MR', 'Sample material request', 'ui', 'short', 0, 'submit', 'migration', 'reference_seed');
